CREATE TYPE "accreditation_status" AS ENUM ('pending', 'approved', 'revoked');
CREATE TYPE "credential_lifecycle" AS ENUM ('active', 'suspended', 'revoked', 'expired', 'superseded');
CREATE TYPE "issuer_key_status" AS ENUM ('active', 'retired', 'revoked', 'compromised');
CREATE TABLE "institutions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "legal_name" text NOT NULL, "country" text NOT NULL, "did" text NOT NULL UNIQUE, "issuer_address" text NOT NULL, "accreditation_status" "accreditation_status" NOT NULL DEFAULT 'pending', "accreditation_valid_from" timestamptz, "accreditation_valid_until" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "issuers" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "institution_id" uuid NOT NULL REFERENCES "institutions"("id"), "did" text NOT NULL UNIQUE, "authorized_credential_types" jsonb NOT NULL, "active" boolean NOT NULL DEFAULT true, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "issuer_keys" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "issuer_id" uuid NOT NULL REFERENCES "issuers"("id"), "verification_method" text NOT NULL UNIQUE, "public_key" text NOT NULL, "status" "issuer_key_status" NOT NULL DEFAULT 'active', "valid_from" timestamptz NOT NULL, "valid_until" timestamptz, "revoked_at" timestamptz);
CREATE TABLE "accreditations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "institution_id" uuid NOT NULL REFERENCES "institutions"("id"), "status" "accreditation_status" NOT NULL, "valid_from" timestamptz, "valid_until" timestamptz, "source_reference" text, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "credentials" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "credential_id" text NOT NULL UNIQUE, "institution_id" uuid NOT NULL REFERENCES "institutions"("id"), "issuer_id" uuid NOT NULL REFERENCES "issuers"("id"), "credential_document" jsonb NOT NULL, "subject_reference" text NOT NULL, "credential_type" text NOT NULL, "issued_at" timestamptz NOT NULL, "status_index" integer NOT NULL, "status_list_id" text NOT NULL, "lifecycle" "credential_lifecycle" NOT NULL DEFAULT 'active', "reason" text, "superseded_by_credential_id" text, "verification_url" text, "qr_code_data_url" text, "storage_cid" text, "blockchain_reference" text, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "credential_versions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "credential_id" text NOT NULL REFERENCES "credentials"("credential_id"), "version" integer NOT NULL, "supersedes_credential_id" text, "superseded_by_credential_id" text, "created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "credential_status_history" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "credential_id" text NOT NULL REFERENCES "credentials"("credential_id"), "status" "credential_lifecycle" NOT NULL, "reason" text, "changed_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "verification_records" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "credential_id" text NOT NULL, "trusted" boolean NOT NULL, "evidence" jsonb NOT NULL, "verified_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE "audit_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "event_type" text NOT NULL, "entity_id" text NOT NULL, "metadata" jsonb NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now());
ALTER TABLE "institutions" ADD COLUMN "external_id" text NOT NULL UNIQUE;
ALTER TABLE "issuers" ADD COLUMN "external_id" text NOT NULL UNIQUE;
CREATE TABLE "students" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "external_id" text NOT NULL UNIQUE, "institution_id" uuid NOT NULL REFERENCES "institutions"("id"), "full_name" text NOT NULL, "email" text NOT NULL);
CREATE INDEX "issuers_institution_id_idx" ON "issuers" ("institution_id");
CREATE INDEX "credentials_issuer_id_idx" ON "credentials" ("issuer_id");
CREATE INDEX "credentials_lifecycle_idx" ON "credentials" ("lifecycle");
CREATE INDEX "credential_versions_credential_id_idx" ON "credential_versions" ("credential_id");
CREATE INDEX "credential_status_history_credential_id_idx" ON "credential_status_history" ("credential_id");
CREATE INDEX "verification_records_credential_id_idx" ON "verification_records" ("credential_id");
